-- supabase/sql/exam_question_bank_upsc_epfo_set1.sql
--
-- First curated question-bank batch for 'UPSC EPFO' (see exam_patterns_upsc_epfo.sql for the
-- exam's structure). Same exam_question_bank table/schema as the other sets -- no migration
-- needed.
--
-- Every row here is format='mcq' with a single isCorrect:true option (100% single-best-response,
-- matching the real exam). The "Current Affairs" chapter sticks to durable, evergreen facts
-- (ministry affiliations, founding years, headquarters) rather than time-sensitive news. 16
-- chapters (2 English, 4 GK/Social Studies, 2 Accounting, 2 Industrial Relations/Labour Law, 2
-- Science/Computer, 4 Quant/Reasoning) each get 4 questions.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_upsc_epfo.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- General English: Grammar and Usage
('UPSC EPFO', 'General English', 'Grammar and Usage', 'medium', 'mcq',
 'Choose the grammatically correct sentence:',
 '[{"text":"The team of players are practicing hard for the tournament.","isCorrect":false},{"text":"The team of players is practicing hard for the tournament.","isCorrect":true},{"text":"The team of players is practicing hard for the tournaments.","isCorrect":false},{"text":"The team of players were practicing hard for the tournament, is it.","isCorrect":false}]'::jsonb,
 null, '"Team" is a singular collective noun (treated as one unit here), so it takes the singular verb "is", not the plural "are".'),
('UPSC EPFO', 'General English', 'Grammar and Usage', 'easy', 'mcq',
 'Choose the correct preposition to complete: "He is responsible ___ the project''s success."',
 '[{"text":"of","isCorrect":false},{"text":"for","isCorrect":true},{"text":"with","isCorrect":false},{"text":"about","isCorrect":false}]'::jsonb,
 null, 'The idiomatic preposition used with "responsible" is "for" -- "responsible for the project''s success".'),
('UPSC EPFO', 'General English', 'Grammar and Usage', 'medium', 'mcq',
 'Which of the following sentences is correctly punctuated?',
 '[{"text":"After the meeting the manager, left for the airport.","isCorrect":false},{"text":"After the meeting, the manager left for the airport.","isCorrect":true},{"text":"After, the meeting the manager left for the airport.","isCorrect":false},{"text":"After the meeting the manager left, for the airport.","isCorrect":false}]'::jsonb,
 null, 'A comma correctly follows the introductory phrase "After the meeting" to separate it from the main clause "the manager left for the airport".'),
('UPSC EPFO', 'General English', 'Grammar and Usage', 'medium', 'mcq',
 'What is the correct passive voice form of "The manager approved the proposal"?',
 '[{"text":"The proposal was approved by the manager.","isCorrect":true},{"text":"The proposal is approved by the manager.","isCorrect":false},{"text":"The proposal has approved the manager.","isCorrect":false},{"text":"The manager was approved by the proposal.","isCorrect":false}]'::jsonb,
 null, 'The past simple active sentence "The manager approved the proposal" becomes "The proposal was approved by the manager" in the passive voice, keeping the same past tense.'),

