('UPSC EPFO', 'General English', 'Vocabulary and Comprehension', 'medium', 'mcq',
 'Choose the word closest in meaning to "Prudent".',
 '[{"text":"Judicious","isCorrect":true},{"text":"Reckless","isCorrect":false},{"text":"Careless","isCorrect":false},{"text":"Impulsive","isCorrect":false}]'::jsonb,
 null, '"Prudent" means acting with care and good judgment; "judicious" is its closest synonym among the options.'),
('UPSC EPFO', 'General English', 'Vocabulary and Comprehension', 'medium', 'mcq',
 'Choose the antonym of "Frugal".',
 '[{"text":"Thrifty","isCorrect":false},{"text":"Extravagant","isCorrect":true},{"text":"Economical","isCorrect":false},{"text":"Sparing","isCorrect":false}]'::jsonb,
 null, '"Frugal" means economical or sparing in the use of resources; its antonym is "extravagant", meaning spending lavishly.'),
('UPSC EPFO', 'General English', 'Vocabulary and Comprehension', 'easy', 'mcq',
 'Choose the correctly spelled word.',
 '[{"text":"Neccessary","isCorrect":false},{"text":"Necessary","isCorrect":true},{"text":"Neccesary","isCorrect":false},{"text":"Necesary","isCorrect":false}]'::jsonb,
 null, '"Necessary" is the correct spelling, with a single "c" and double "s".'),
('UPSC EPFO', 'General English', 'Vocabulary and Comprehension', 'medium', 'mcq',
 'Choose the word that best completes the sentence: "The auditor''s ___ review uncovered several discrepancies."',
 '[{"text":"Thorough","isCorrect":true},{"text":"Careless","isCorrect":false},{"text":"Superficial","isCorrect":false},{"text":"Hasty","isCorrect":false}]'::jsonb,
