 '[{"text":"100","isCorrect":true},{"text":"80","isCorrect":false},{"text":"120","isCorrect":false},{"text":"90","isCorrect":false}]'::jsonb,
 null, '25% of 400 = (25/100)*400 = 100.'),
('UPSC EPFO', 'Quantitative Aptitude and Reasoning', 'Quantitative Aptitude - Arithmetic', 'medium', 'mcq',
 'Two numbers are in the ratio 3:4, and their sum is 70. Find the larger number.',
 '[{"text":"30","isCorrect":false},{"text":"40","isCorrect":true},{"text":"35","isCorrect":false},{"text":"45","isCorrect":false}]'::jsonb,
 null, 'Let the numbers be 3x and 4x; 3x+4x=70 gives x=10, so the larger number is 4*10=40.'),

